// Deterministic classic runtime bundle; original pure/store modules remain separate/testable.
import fs from 'node:fs';
const root = new URL('../', import.meta.url);
const modules = [
  ['core', 'metrics-core.mjs', ''],
  ['store', 'metrics-store.mjs', 'const {ENGINE_VERSION, DEFAULT_REGISTRY, createRegistry, metricPeriod, validDate, koreaDate, calculateMonth}=core;'],
  ['dashboard', 'dashboard-runtime.mjs', 'const {DEFAULT_REGISTRY, calculateMonth, compareMetric, resolveGoal, previousMonth, koreaDate}=core; const {createMetricsStore, prepareSnapshot}=store;']
];
const parts = modules.map(([name, file, dependencies]) => {
  const source = fs.readFileSync(new URL('data-hub/' + file, root), 'utf8').replace(/\r\n/g, '\n');
  const exports = [...source.matchAll(/export (?:async )?(?:function|const) (\w+)/g)].map(match => match[1]);
  const body = source.replace(/^import .*;\r?\n/gm, '').replace(/export /g, '');
  return `const ${name}=(()=>{\n${dependencies}\n${body}\nreturn Object.freeze({${exports.join(',')}});\n})();`;
});
const bundle = `// Generated by scripts/hani-data-hub-bundle.mjs. Do not edit directly.\n(()=>{\n'use strict';\n${parts.join('\n')}\nwindow.HANI_DATA_HUB=Object.freeze({...dashboard});\n})();\n`;
// Embed the generated region in the existing entrypoint: no extra runtime file,
// and no change to the protected release file-count or byte-size limits.
const target = new URL('hani-main.js', root);
const start = '// BEGIN GENERATED HANI DATA HUB';
const end = '// END GENERATED HANI DATA HUB';
const region = `${start}\n${bundle}${end}`;
const main = fs.readFileSync(target, 'utf8');
const pattern = /\/\/ BEGIN GENERATED HANI DATA HUB[\s\S]*?\/\/ END GENERATED HANI DATA HUB/;
const existing = main.match(pattern);
if (process.argv.includes('--check')) {
  if (!existing || existing[0].replace(/\r\n/g, '\n') !== region) throw new Error('STALE_DATA_HUB_BUNDLE');
} else {
  if (!/^\s*"use strict";/.test(main)) throw new Error('UNEXPECTED_MAIN_ENTRYPOINT');
  const output = existing ? main.replace(pattern, region) : main.replace('"use strict";', `"use strict";\n${region}\n`);
  fs.writeFileSync(target, output.replace(/(\/\/ END GENERATED HANI DATA HUB)\s+(?=const VERSION=)/, '$1\n'));
}
